# EVENT         the 175 modern sphere events, keyed sphere.event: name, tone (good, bad, mixed), the line as the town
#               sees it, and self: how it touches the character
EVENT = {
    'rule.feud_settled': dict(name='A feud is settled', tone='good', line="Mediation ends the neighbours' long fight over the fence. They nod to each other at the bins now.", self='They sit down to eat with the family they were taught to hate; they may pay or get part of the price, and may now marry or trade across the line.'),
    'rule.new_leader': dict(name='A new leader is chosen', tone='mixed', line="Election night: the other side wins by a few hundred votes, and the council's plans change by morning.", self='A new chief, lord or council changes who is in favour; a door opens for a friend or shuts on their kin. They can court the new people, or keep away.'),
    'rule.favour_exposed': dict(name='Favour exposed', tone='mixed', line='A leak shows the building permits followed the donations. The councillor resigns; the permits stand.', self='Someone they know is named: the cousin who got the post, or the official whose bribe they refused. They can speak up, defend a friend, or keep quiet.'),
    'rule.petition_granted': dict(name='A petition is granted', tone='good', line='The petition passes the number that forces a debate, and the bus route to the hospital is saved.', self='If they signed or carried it, they learn their voice counts; if they led it, their standing rises.'),
    'rule.rising': dict(name='A rising', tone='mixed', line='The protests swell for weeks until the government falls. Nobody knows yet what comes after.', self='They choose: join, hide, shelter a neighbour, or stand by the old rule. Work and safety are at risk.'),
    'rule.reform_wave': dict(name='A reform wave', tone='good', line="The new government's first year: a lobbying register, faster courts, and free legal advice for tenants.", self='A new rule opens a door: a loan they can now get, a school their child may attend, a fee abolished.'),
    'rule.restoration': dict(name='The old ways return', tone='mixed', line="The vote swings back: some of the last government's laws are repealed, to some people's relief and others' grief.", self='A freedom they used narrows, or a way of life their parents mourned is honoured again; which, depends on who they are.'),
    'rule.power_seized': dict(name='Power is seized', tone='bad', line='The armed forces take power overnight. The council is dissolved, and a curfew begins.', self='Their seat, their voice or their faction is shut; some of their people prosper, others flee. They can serve, keep their heads down, or leave.'),
    'rule.unjust_verdict': dict(name='An unjust verdict', tone='bad', line="The court clears the builder who ignored the safety rules. The injured workers' families leave the hearing in silence.", self='They or their kin lose a case they should have won, or watch a neighbour lose one. They can appeal, find a patron, or take it to the street.'),
    'rule.amnesty': dict(name='An amnesty', tone='good', line="An amnesty for last year's protesters: records cleared, and a few old wounds reopened.", self='A brother comes home, or the man who wronged them walks free; often both at once.'),
    'rule.new_levy': dict(name='A new levy', tone='bad', line="A new charge on every household's water bill. The town meeting is fuller than it has been in years.", self='Their household pays more, hides what it can, or joins those who refuse.'),
    'rule.landmark_ruling': dict(name='A landmark ruling', tone='good', line='The high court rules that two men or two women may marry. Some families celebrate; some argue at dinner.', self='Something they or someone they love could not do, they now may; or the reverse.'),
    'rule.say_widened': dict(name='The say is widened', tone='good', line='The voting age is lowered. At the next election, the young queue at the polling station beside their parents.', self='They, or their mother, can vote or sit in the assembly for the first time.'),
    'rule.rights_narrowed': dict(name='Rights narrowed', tone='bad', line='After the attack, new powers: protests need permits, and messages can be read without a warrant.', self='Their haunt closes early, a friend is questioned, and a door shuts by law.'),
    'rule.charter_won': dict(name='A town wins its own rule', tone='good', line='The district wins its own council after a ten-year campaign. The first meeting runs four hours over.', self="Their town's quarrels are now heard at home; a seat on its council is within reach."),
    'rule.deadlock': dict(name='Deadlock', tone='bad', line="The budget fails for the third time. Offices close at noon, and nobody's grant is paid.", self='What they were waiting for, a permit, a well or a wage, does not come.'),
    'rule.false_accusation': dict(name='A false accusation', tone='bad', line='A death after an emergency call spreads online. The paramedic who went in first is named before any inquiry meets.', self='Someone they know, perhaps someone who once helped them, is accused: they speak for them, stay silent, or join the accusers.'),
    'rule.the_count': dict(name='The count of people and land', tone='mixed', line="The census form arrives. A counter knocks on the doors that did not answer, and the street's funding for ten years hangs on the total.", self='The counters come to their door: they can give true numbers, leave a field off the list, or pay the clerk to look away.'),
    'rule.conquest': dict(name='Conquered', tone='bad', line='After the ceasefire the region is ruled from the other capital: new flags, new forms, and a new language at the school gate.', self='Their people are ruled by strangers: they can serve the new masters, keep their heads down, teach the old tongue at home, or join those who resist.'),
    'rule.strangers_expelled': dict(name='A people is driven out', tone='bad', line="A new law strips residence from a whole community. Families on the street have a month to leave; a neighbour keeps one family's keys.", self='Neighbours are driven out: they can shelter a family, speak at the hearing, look away, or buy what is sold cheap.'),
    'rule.patron_delivers': dict(name='The patron delivers', tone='mixed', line='The councillor fights the budget all night and wins the estate its playground. Her rivals call it buying votes; the families call it theirs.', self='Their street gets what it waited for. They can thank the patron with a vote, work for them, or say aloud what the bargain cost.'),
    'gather.great_feast': dict(name='A great feast', tone='good', line="The neighbours close the street for a night: long tables, music, everyone's best dish.", self='A night at the long table: new friends, perhaps a partner met across it, and a memory for life.'),
    'gather.meeting_place_opens': dict(name='A new meeting place opens', tone='good', line='A café opens on the corner, with long tables and a board of what is on this week.', self='A new haunt to try and new faces; the old place feels quieter, and loyalty is tested.'),
    'gather.keeper_dies': dict(name='The old keeper dies', tone='mixed', line="The bar's owner of thirty years has died. The regulars hold the wake in the bar itself.", self='Grief for someone who knew everyone; a chance to take the place on, or to watch it change.'),
    'gather.brawl': dict(name='A brawl', tone='bad', line='Outside the club at closing time a shove becomes a fight, and someone goes to hospital.', self='A friend hurt. Step in, step back, fetch help, or speak later to the elders or the watch.'),
    'gather.curfew': dict(name='Curfews and closing hours', tone='bad', line='Bars must close at ten. The streets go quiet, and the parties move into flats and basements.', self='Their haunt closes early. Comply, protest, or find the back door.'),
    'gather.drink_banned': dict(name='Drink is banned', tone='bad', line='Drink is banned. Clubs serve it in teacups, and the bribes go up every month.', self='The tavern becomes a back room with a knock. Keep going, join the temperance hall, or run crates.'),
    'gather.hall_lost': dict(name='The meeting house is lost to fire or flood', tone='mixed', line='A flood ruins the community centre; for a year its groups meet in kitchens, or not at all.', self='A season of rebuilding with neighbours, or the end of a place they grew up in.'),
    'gather.peace_feast': dict(name='The first feast after', tone='good', line='The war is over and the soldiers are home. The street puts out long tables, and the bars stay open until dawn.', self='A night they remember for life: the first dance after the long fear, and maybe the person they will marry.'),
    'gather.slump_shifts': dict(name='Hard times move the evenings', tone='mixed', line='Work is scarce. The smart bar shuts; the old corner bar and the community centre are full.', self="Evenings move to the cheap tavern or the hall's soup night; a friend leaves town for work."),
    'gather.great_fair': dict(name='The great fair comes', tone='good', line='The convention fills the hall for three days: stalls, talks, and old friends seen once a year.', self='Strangers, music and news; a chance to trade, show, compete, or meet someone from far away.'),
    'gather.doors_close': dict(name='Doors close to newcomers', tone='bad', line='The club raises its fee and adds a waiting list. The new families start their own club across town.', self='Turned away at the door, or asked to vote someone out; either way, a choice about who they are.'),
    'gather.informer': dict(name='An informer at the table', tone='bad', line='Someone in the group passes messages on. A friend loses their job over a joke made at the bar.', self='A friend taken for something said over drinks. Whom do they trust now?'),
    'gather.evenings_home': dict(name='Evenings move home', tone='mixed', line='Screens in every room and a long drive home: the team folds for lack of players.', self='Cosy nights in, and a club that folds for want of a secretary.'),
    'gather.society_wave': dict(name='A wave of societies', tone='good', line="Volunteers start a dozen groups in a year: a running club, a repair night, a parents' circle.", self='A choir, a team, a burial club or a reading society asks them to join, then to serve.'),
    'gather.the_games': dict(name='The great games', tone='good', line='The final is on. Every bar has a screen, strangers hug, and the whole street hears the goal.', self='Play, cheer or wager: a day that makes a name, a friend on the next bench, or a loss that stings for a year.'),
    'gather.rumour_runs': dict(name='A rumour runs', tone='bad', line="A post claims the town's water is poisoned. By night it has been shared a thousand times, and the shops are out of bottled water.", self='They hear the tale early. Pass it on, ask for proof, stand by the people it names, or keep quiet.'),
    'gather.news_sheet': dict(name='News by a new road', tone='mixed', line='A local news feed starts up. Within a month every phone in town carries the prices, the scores and who has died.', self='Their name, a wedding or a quarrel passed round as news, and something new to argue about at every table.'),
    'gather.common_ground': dict(name='A square for everyone', tone='good', line='The old rail yard becomes a park with a skate bowl, a market square and long benches. On summer nights half the town is there.', self='A free place to walk, play and meet someone from beyond their own kin and neighbours.'),
    'arts.new_sound': dict(name='A new sound takes hold', tone='good', line='A few clubs in the old warehouse quarter play a sound no one has a name for yet. The queue goes round the block.', self='If young and there: a haunt, a crowd and a sound that is theirs for life. If older, a noise next door to join, ignore or complain about.'),
    'arts.scene_sells': dict(name='The scene sells', tone='mixed', line='The sound is in every advert now. The first club is a chain bar, and the old crowd have moved on.', self="Some of their old crowd get rich and others feel robbed; years later they hear their youth's sound selling soap."),
    'arts.work_banned': dict(name='A work is banned', tone='bad', line='A film is pulled from cinemas after a campaign against it. Copies spread from phone to phone within days.', self='A show or song they love is gone. They comply, find the hidden room, or say something aloud.'),
    'arts.last_teller': dict(name='The last keeper of the old tellings dies', tone='bad', line='Their great-aunt, the last who sang the old songs in the old tongue, dies. The recordings were on a lost phone.', self='Grief, and a question: learn what is left, write it down, or let it go.'),
    'arts.old_songs_return': dict(name='The old songs come back', tone='good', line='A folk festival fills a field for a weekend. Teenagers learn the old dances from grandparents in the queue.', self="A grandparent's song is wanted again; they are asked to sing it, teach it, or join the dance."),
    'arts.work_of_the_day': dict(name='A work everyone talks about', tone='mixed', line='Everyone is watching the same series. At work, at dinner and online, the argument about its ending will not stop.', self='They see or hear it and argue about it at the table; a view of theirs may shift, or harden.'),
    'arts.patron_builds': dict(name='A patron pays for the arts', tone='good', line="A new fortune funds an arts centre in the old station. The founder's name is on everything.", self='A new stage in town: a job backstage, a seat in the gallery, or an audition.'),
    'arts.stages_go_dark': dict(name='Hard times silence the players', tone='bad', line='The slump closes two theatres and the music venue. The local band plays kitchen parties instead.', self='If they perform, the work dries up; evenings move to the kitchen, where the old songs come back.'),
    'arts.new_medium': dict(name='A new way to carry art arrives', tone='mixed', line='Every song ever recorded is now on the phone in their pocket. The local cover band loses its weekly night.', self='A new way to hear and see the world; a job lost or a door opened, depending on their craft.'),
    'arts.songs_of_war': dict(name='Songs of war, then songs of loss', tone='mixed', line='The anthem is on every screen. A year on, the song everyone shares is about an empty chair at the table.', self='The song they marched to or waved someone off with, and later the song that makes them cry.'),
    'arts.mocking_song': dict(name='A mocking song brings down the proud', tone='mixed', line="A comedian's sketch about a minister goes everywhere online. The minister's apology makes it worse.", self='Everyone hums it. They wonder whether to sing along in public, and who will be mocked next.'),
    'arts.local_fame': dict(name='A local voice wins fame', tone='good', line="A classmate's song goes everywhere online. Suddenly old schoolmates are posting photos with them.", self='Someone they know is famous: a spark for a dream, a pang of envy, perhaps a door.'),
    'arts.star_falls': dict(name='A famous name falls', tone='bad', line="A celebrated director's bullying of the cast comes out. Some fans throw out the films; others will not hear a word.", self='A hero of theirs falls: they defend them, drop them, or quietly keep loving the work.'),
    'arts.house_closes': dict(name='The old theatre closes', tone='bad', line='The little theatre on the main street is closing for flats. The final show sells out in an hour.', self='Their haunt or workplace is gone: the last night together, or the chance to fight to save it.'),
    'arts.far_market': dict(name='Their crafts find a far market', tone='mixed', line='Visitors buy the village pottery online and in the square. Young potters come back from the city.', self='The family craft suddenly pays; they choose whether to keep the old patterns or make what sells.'),
    'arts.school_of_arts': dict(name='A place to learn the arts opens', tone='good', line='A free music school opens in the community centre, with instruments to borrow.', self='A door: an audition, a place paid for by the school, or a job teaching there.'),
    'arts.images_condemned': dict(name='Images and songs condemned', tone='bad', line="The new regime bans the old songs and wipes the archive's recordings. Copies survive on a few phones.", self='A carving their family kept is burned, or a song is now sung only in whispers at home.'),
    'arts.home_tongue_written': dict(name='Stories in the home tongue', tone='good', line='A novel in the tongue their grandparents were punished for speaking at school becomes a hit. Teenagers quote it to each other online.', self='A story in the words their family speaks at home: they read it aloud at the table, write their own, or keep to the high tongue for standing.'),
    'arts.benefit_night': dict(name='A benefit night for the stricken', tone='good', line='After the flood, a famous band from the town comes home for a free concert. The donations rebuild the youth club.', self='They give, play, or are the ones given to: a night of thanks, and favours owed for years.'),
    'faith.faith_revival': dict(name='A revival sweeps through', tone='mixed', line='A new congregation meets in an old warehouse: loud music, tears, and three hundred people every week.', self='A friend invites them to the meetings: stay away, go once, or go and be changed.'),
    'faith.coming_of_age': dict(name='The coming-of-age rite', tone='good', line='The ceremony is short; the party lasts all afternoon. A grandparent cries and will not say why.', self='A time apart, a test of skill or knowledge, the lore told, then a feast; the peers from it stay close.'),
    'faith.pilgrimage': dict(name='Pilgrimage season', tone='good', line='The old walking road is full again: believers, seekers and the merely curious, all with blisters.', self='A long walk with strangers who become friends; a promise kept, a question carried, the wider world seen.'),
    'faith.scandal': dict(name='A scandal in the faith', tone='bad', line='The news breaks: the faith leader spent the building fund on himself. Attendance falls by half.', self='Someone they trusted is named. Do they stay, speak up, or quietly stop going?'),
    'faith.new_teaching': dict(name='A new teaching takes root', tone='mixed', line='A small group meets online, then in a rented room: a new teaching, and a founder people love.', self='A friend joins and glows with it, and asks them to come and see.'),
    'faith.schism': dict(name='The faith splits', tone='bad', line='The congregation splits over who may lead. One side keeps the building; the other rents a school hall.', self="Their congregation divides. Their parents go one way and their partner's family the other."),
    'faith.faith_outlawed': dict(name='A faith is outlawed', tone='bad', line='The government lists the faith as dangerous. Members lose jobs; services move into private homes.', self="A neighbour's family keeps a secret. Hide their book, report them, or look away?"),
    'faith.tolerance': dict(name='Peace between the faiths', tone='good', line='Leaders of every faith in town share a meal. It makes the local paper, and it is a start.', self="A friend of another faith can now marry openly, and the town's festivals multiply."),
    'faith.sign': dict(name='A sign at the shrine', tone='mixed', line='A clip of a face in a window goes everywhere. By the weekend, cars line the road outside.', self='Someone close is healed, or believes they are. The story never says what happened; the character decides what to believe.'),
    'faith.rites_cut': dict(name='Too many dead for the rites', tone='bad', line='The funeral was allowed ten people. The rest watched on a screen, and no one could hug.', self='A funeral no one could attend properly. Years later, a second rite to say goodbye.'),
    'faith.temple_raised': dict(name='A new house of worship is raised', tone='good', line="After ten years of fundraising the new building opens. Children's drawings line the hallway.", self='Work on the build, a name carved on a stone, or a family bench kept for generations.'),
    'faith.young_drift': dict(name='The young drift away', tone='mixed', line="None of their friends go anymore. They still light the candles at the holidays, at their parents' house.", self="Freer rest days, a parent's sorrow, a wedding without a priest. Some come back at a birth or a death."),
    'faith.holy_days': dict(name='The fast and the feast', tone='good', line='Everyone comes home for the holidays: the old arguments, the same dishes, someone new at the table.', self='Days of hunger and quiet, then the table full, and the one empty chair everyone notices.'),
    'faith.calling': dict(name='A calling', tone='mixed', line='In their thirties, after a loss, they train as a faith counsellor. Their friends do not know what to say.', self='They, or someone close, feel called: years of training, a new name, and work that may cost a family of their own.'),
    'faith.grove_felled': dict(name='The sacred grove is cut', tone='bad', line='A developer clears the hill where people left offerings for generations. A protest camp forms.', self='Join the clearing, or stand with those who would keep the grove. At home, someone will not speak of it.'),
    'faith.temple_feeds': dict(name='The temple feeds the town', tone='good', line="The food bank in the faith's hall now opens five days a week. Half the volunteers are not believers.", self="In the hard months they eat at the temple's table, or serve at it."),
    'faith.holy_war': dict(name="War in the faith's name", tone='bad', line="Abroad, a war is fought in the faith's name. At home, a neighbour's shop window is broken.", self='A preacher calls for volunteers and a brother goes. A neighbour of the other faith asks the family for help.'),
    'faith.succession': dict(name="The faith's old leader dies", tone='mixed', line="The congregation's leader of thirty years retires. The search committee meets for a year.", self='The one who taught them is gone: a vote, a side to choose, or an offer to step up.'),
    'faith.temple_lands_taken': dict(name="The faith's lands are taken", tone='mixed', line="After the upheaval the faith's estates are split among the farmers who worked them; its great temple becomes a grain store, then a museum.", self='The vowed house where an aunt lived is sold, and a cousin buys a field of it. Join the buyers, shelter the turned-out, or petition the rule.'),
    'faith.marriage_across': dict(name='A marriage across the faiths', tone='good', line='The wedding has two rites back to back, one grandmother from each side, and music that offends everyone a little.', self='A friend, a sibling or the character marries across the line: stand with them, ask one of them to change faith, or stay away.'),
    'faith.endowment': dict(name="A patron endows the faith's works", tone='good', line="A businesswoman leaves her fortune to the faith's food bank. A plaque goes up, and so does a new kitchen.", self='A table, a bed or a schooling paid for by someone long dead, or the chance to leave a gift of their own.'),
    'faith.funeral': dict(name='A funeral in the family', tone='mixed', line='The funeral director is kind and the bill is not. The cousins split it, and someone sings the old song at the grave.', self='A death close by: what to spend, who speaks, and whether to borrow so the family is not shamed.'),
    'care.plague_wave': dict(name='A plague comes', tone='bad', line='A new virus spreads faster than the tests. Wards fill, bars and gyms shut by order, and friends meet on screens, then not at all.', self='Fear at home: nurse the sick, flee, or go out to help; months apart from friends, and a death they cannot mourn together.'),
    'care.quarantine': dict(name='The way in is shut', tone='mixed', line="Lockdown. Shops shut, the streets go quiet, and the family learns the shape of each other's days.", self='Weeks shut in: time with family rises, money falls; keep the rules, slip past them, or carry food to those shut in.'),
    'care.neighbours_rush': dict(name='Neighbours rush to help', tone='good', line='The storm cuts the power. Neighbours check on the old, share generators and drive the sick to the clinic.', self='Pulling a neighbour from the ruins, or being pulled out; ties with strangers made in one night.'),
    'care.remedy_works': dict(name='A remedy that works', tone='good', line='A new drug turns a death sentence into a long illness. The pharmacy queue is the happiest place in town.', self='An illness that once killed is now survivable; someone they love lives who would not have.'),
    'care.cure_fails': dict(name='A cure that harms', tone='bad', line='A new pill, approved in a hurry, is linked to heart attacks. It is withdrawn, the lawsuits begin, and patients ask harder questions.', self='Someone close took the new cure: anger, a complaint, joining others who were harmed, or a quiet distrust of the next one.'),
    'care.remedy_feared': dict(name='A remedy is feared', tone='mixed', line='A rumour about the new vaccine spreads faster than the virus. A family dinner ends in silence.', self='Take it, refuse it, decide for their children, or argue with a sister who chose the other way.'),
    'care.birth_safer': dict(name='Births grow safer', tone='good', line='The new maternity unit opens with a midwife-led birth centre beside it. Families choose.', self='A sister or partner comes through a hard birth alive; the family grows.'),
    'care.hard_birth': dict(name='A hard birth', tone='mixed', line='The labour stalls in the night. The midwife calls the surgical team, and within the hour mother and baby are safe.', self="A sister's or partner's long labour: run for help, keep the fire, hold her hand. Mother and child come through, or the family grieves together."),
    'care.good_death': dict(name='A good death', tone='good', line='The hospice nurse comes every day. Their father dies at home, in his own bed, without pain.', self='A parent dies in comfort with the family around them, and the grief that follows is lighter for it.'),
    'care.house_of_care_opens': dict(name='A house of care opens', tone='good', line='A clinic opens in the neighbourhood: a doctor, two nurses, and evening hours that fit working people.', self="A bed for the poor nearby; a post as a carer; a benefactor's name they will pass every day."),
    'care.water_clean': dict(name='Clean water comes', tone='good', line='The water plant is rebuilt after the scandal. For the first time in years, people drink from the tap.', self="Clean water at the pump or tap; fewer summer fevers; the family's youngest live to grow up."),
    'care.old_ways_fade': dict(name='The old remedies fade', tone='mixed', line="A pharmacist finds that the old woman's tea really works, a year after the old woman has died.", self="Grandmother's cough remedy that no one else remembers: write it down, ask her to teach it, or let it go."),
    'care.sick_club': dict(name='The sick club', tone='good', line='Neighbours start a mutual aid group: a shared fund, a list of who can drive, and meals for whoever is ill.', self='They pay a coin a week; when they fall ill, the club pays the doctor and a weekly sum, and buries its own decently.'),
    'care.old_age_kept': dict(name='The old are provided for', tone='good', line="Their mother's pension and a visiting carer let her stay in her own flat, near the grandchildren, with her own key.", self='A parent kept with dignity, and time back for their own work; pay into the fund, or keep the old one at home.'),
    'care.care_for_all': dict(name='Care for all', tone='mixed', line='Care becomes free at the point of need. The queues are long, and no one gets a bill.', self='An operation for a parent they could never have paid for, and a longer wait for their own.'),
    'care.fees_rise': dict(name='Care priced beyond reach', tone='bad', line='The insurance will not cover it. The family starts a fundraiser and sells the car.', self='A bill they cannot pay: borrow, sell something, go without, or find the healer who treats for nothing.'),
    'care.hands_short': dict(name='Not enough hands', tone='bad', line="The care home's staff change every few months, and the agency nurses do not know the residents' names.", self="A parent's care falls to them and their work hours are cut; or a well-paid post as a carer opens."),
    'care.war_wounded': dict(name='The wounded come home', tone='mixed', line='Veterans come home with injuries the eye cannot see. The clinic opens a team just for them.', self='A brother or neighbour comes home hurt and changed: they nurse him, or serve as a field healer and come back changed too.'),
    'care.healer_famed': dict(name='A healer makes a name', tone='mixed', line='A surgeon on the evening news pioneers a new operation. The waiting list runs two years.', self='A long journey to the famous healer for someone they love; or a chance to apprentice with them.'),
    'care.neglect_scandal': dict(name='A scandal of neglect', tone='bad', line='Hidden camera footage from a care home is on every screen. The owners resign; the inspectors return.', self='A relative was in that house: anger, a complaint, a choice to testify, or to care for them at home instead.'),
    'learn.knowledge_lost': dict(name='A skill dies with its keeper', tone='bad', line="The engineer who understood the town's old water system retires. When it fails, nobody can find the drawings.", self='Something their family or town could do is gone; they may try to rebuild it from fragments, or let it go.'),
    'learn.first_school': dict(name='A school opens where there was none', tone='good', line='A new school opens across the river, so the children no longer take the early bus out of town.', self='A door: the first in the family to read, or to send a child to school; a teacher enters the cast.'),
    'learn.academy_founded': dict(name='A house of higher learning is founded', tone='good', line='A university campus opens on the old army base. Rents rise, cafes open, and the town fills with the young.', self='A door to study, if they can get in; the town fills with the young and restless; new work in lodging and service.'),
    'learn.schools_for_all': dict(name='Schooling is made free and required', tone='mixed', line='The leaving age rises by two years. The older pupils grumble; the trade schools fill.', self='Years of school instead of work: a door for most, lost hands at home, and perhaps the home tongue shamed at school.'),
    'learn.the_exam': dict(name='The great examination', tone='mixed', line='A week of entrance exams, a summer of waiting, and a number that decides which doors are open.', self='Months of preparation; a pass opens a post, a place or a licence, and a fail closes it for a year or for good.'),
    'learn.discovery': dict(name='Something new is found', tone='good', line='A lab at the regional university finds a cheaper way to store power. The local works hire two hundred people.', self='The world shifts a little: a new tool, a cure, a new picture of the sky; a hand in it brings standing and meaning.'),
    'learn.censors_close': dict(name='Questions are forbidden', tone='bad', line='After complaints the council pulls a dozen books from the school library. Teachers are told which topics to avoid.', self='A teacher dismissed, a book to hide or hand in: comply, hide it, report it or leave.'),
    'learn.learned_leave': dict(name='The learned leave', tone='bad', line='Half the graduating class takes jobs abroad. Their parents follow their lives on video calls.', self='A friend, sibling or child leaves for study or work far away; or they go themselves and weigh what they leave behind.'),
    'learn.learned_arrive': dict(name='Skilled strangers arrive and teach', tone='good', line='Doctors and engineers who fled a war abroad retrain and teach at the college. Its labs double in a decade.', self='A new teacher, master or neighbour with other knowledge; a new trade to learn; perhaps a rival for their post.'),
    'learn.free_library': dict(name='A library opens to all', tone='good', line="The library reopens after the refit, with study rooms, a makers' workshop and free classes in the evenings.", self='A door: the self-taught road, a quiet place, a new circle of readers; for some, a way out.'),
    'learn.teachers_walk_out': dict(name='The teachers walk out', tone='mixed', line="The teachers strike for six weeks over pay and class sizes. Parents swap days off to mind each other's children.", self='Children at home for weeks; a side to take; if they teach, to walk out with the others or keep the class.'),
    'learn.war_empties_schools': dict(name='War stops the teaching', tone='bad', line='The fighting closes the schools for a year. Lessons go online when the power is on.', self='Years of schooling lost and never quite made up; the classroom becomes a barracks or an infirmary.'),
    'learn.glut_of_learned': dict(name='Too many learned, too few posts', tone='bad', line="Half the year's graduates work jobs that need no degree. A movement of the young starts in the university towns.", self='Their credential buys less than promised: work below it, retrain, emigrate, or join those who want change.'),
    'learn.old_ways_taught': dict(name='The old ways are taught again', tone='good', line="A weekend school teaches the grandparents' language. Children who used to be ashamed of it now correct their parents.", self="A grandparent's words taught in a classroom; a craft to take up; a choice between the old way and the new one."),
    'learn.store_lost': dict(name='The store of books is lost', tone='bad', line="A flood fills the archive's basement overnight. Volunteers freeze the soaked boxes, but the town's oldest registers are lost.", self='A record they needed is gone, or a book they loved: they may help carry books out, rebuild from memory, or let it go.'),
    'learn.newcomer_taught': dict(name='A newcomer is taught the ways', tone='mixed', line='A family from abroad moves into the flat below. The children top their class within a year; the parents still struggle with the forms.', self="A newcomer in the household or class to teach, befriend or keep at arm's length; or the character is the newcomer, learning fast."),
    'prod.rich_season': dict(name='A rich season', tone='good', line='The best harvest in a decade. The silos are full and the co-op pays a bonus, though prices are the lowest in years.', self='Stores or money for the year, a feast, a wedding or a purchase made possible; in market times growers may earn less per measure.'),
    'prod.lean_year': dict(name='A lean year', tone='bad', line="A drought year. The farm's yield is half, the feed has to be bought in, and the bank asks to talk about the loan.", self='Hunger or money worry, kin asking for help, and a choice to share, hoard, leave, or take what is not theirs.'),
    'prod.new_tool': dict(name='A new tool spreads', tone='mixed', line='The plant installs robots on the welding line. Half the welders are trained to program them; the rest are offered a payout.', self="Learn the new way and gain, or keep the old skill as it loses worth; a parent's trade may fade."),
    'prod.rush': dict(name='A rush to new ground', tone='mixed', line='A metal the new batteries need is found under the hills. Rents triple in a year, and the old ranchers sell out or dig in.', self='A chance to go and get rich or get hurt; a sibling or partner leaves; years later, the bust.'),
    'prod.works_close': dict(name='The works closes', tone='bad', line='The plant is moving its line abroad. Eight hundred jobs go, and with them the café opposite, the parts supplier and the late bus.', self='They, a parent or friends lose work: leave for work elsewhere, stay and scrape by, or start something in the ruins.'),
    'prod.walkout': dict(name='The hands walk out', tone='mixed', line='The union calls a strike when the offer falls short of rising prices. Pickets at the gate; the managers run a skeleton shift.', self='Walk out or keep working; pay won or a job lost; a lifelong friend or enemy made on the picket line.'),
    'prod.accident': dict(name='Disaster at work', tone='bad', line='Scaffolding collapses on the building site. The papers run the story for a week; the union says it warned the company twice.', self='Someone close, or the character, hurt or lost; grief, and a choice to stay in the trade or leave, speak up or keep quiet.'),
    'prod.land_taken': dict(name='The land is taken', tone='bad', line='A large farming firm buys out the neighbours one by one. The last family farm in the valley gets an offer it can hardly refuse.', self='Their family loses its field, pasture or fishing rights: work for wages, move, resist, or buy in.'),
    'prod.land_shared': dict(name='The land goes back to those who work it', tone='good', line='The land reform passes. The great estates are split, and thousands of families receive titles to the fields they worked.', self='Land, a holding or a debt freed: a new start, or a lender in the family who loses.'),
    'prod.stock_fails': dict(name='The stock runs out', tone='bad', line="The fish stock collapses. The fishery is closed for ten years, and the harbour town's boats are tied up overnight.", self='The family trade loses its living: a move, a new trade, or a fight over what is left.'),
    'prod.closed_season': dict(name='The commons agree a rest', tone='good', line='The fishing towns set their own quotas with the scientists. After four lean years the stock is counted rising for the first time.', self='A lean season kept for a better one; a neighbour caught cheating; a share in a rule that works.'),
    'prod.scarce_hands': dict(name='Hands are scarce', tone='mixed', line='After the epidemic, kitchens and farms cannot fill their posts. Pay rises for the first time in years, and the farm buys a picking machine.', self='Better pay and more say; or, as an owner, struggling to find and keep hands.'),
    'prod.heir': dict(name='The holding passes on', tone='mixed', line='The third generation does not want the bakery. A chain offers to buy the name; the old baker asks his apprentice instead.', self="Asked to take over the family's holding or firm, to sell it, or to stand aside for a sibling."),
    'prod.coop': dict(name='A shared venture is founded', tone='good', line='The dairy farmers form a cooperative to build their own cheese plant. The big buyer drops its price to break them; they hold together.', self='A share and a vote, long meetings, a stake in the outcome, and a chance to keep the family holding afloat.'),
    'prod.war_works': dict(name='War takes the hands', tone='mixed', line='The war abroad doubles the orders at the plant. Overtime every weekend, and protesters at the gate.', self='Longer hours, new work for those left at home, a chance at a trade once closed to them, or a loss at the front.'),
    'prod.name_won': dict(name='Their make wins a name', tone='good', line="A food writer calls the valley's olive oil the best she has tasted. Visitors come to the presses, and land prices climb.", self='Work with pride and better prices; pressure to keep the old way, or to make more, faster.'),
    'prod.drift_to_town': dict(name='The young leave for bigger places', tone='mixed', line='The school bus leaves the valley half empty. The young are in the city, renting rooms four to a flat and calling home at the weekend.', self='Go to the town for work and freedom, or stay with the land and the old; a sibling or friend leaves and keeps in touch, or does not.'),
    'prod.venture_founded': dict(name='A new venture takes on hands', tone='good', line='A laid-off engineer opens a small firm in a rented unit and hires four of her old crew. The bank said no twice; her aunt said yes.', self='A chance to join a new shop early, put savings in, or start one: risk, long days, and maybe a name of their own.'),
    'comm.lender_fails': dict(name='A great lender fails', tone='bad', line="The bank that held the town's mortgages collapses. Loans are called in, the hardware shop closes, and the news talks of nothing else.", self='Savings frozen or lost, a loan called in, hours cut; they ask kin for help, or are asked, or take a coat to the pawn lender.'),
    'comm.new_route': dict(name='A new route opens', tone='good', line='A new highway and depot open at the edge of town. Trucks arrive at all hours, and jobs come with them.', self='New work on the road or the docks, new goods in the house, strangers in the street; some old trades lose out.'),
    'comm.market_granted': dict(name='A market is granted', tone='good', line='The council opens a weekly market in the empty car park. Growers, bakers and second-hand sellers are set up by eight.', self='A day each week to sell, buy, meet and hear news; perhaps a stall of their own.'),
    'comm.dearth': dict(name='Food grows dear', tone='bad', line="A fuel shock on top of a poor harvest. Food prices jump each month, and the food bank's queue reaches the corner.", self='Meals cut, something sold, a debt run up at the shop; they share what they have, or keep it close.'),
    'comm.crowd_price': dict(name='The crowd sets the price', tone='mixed', line='After the storm a shop triples the price of water. Neighbours picket it, and the council caps prices for a month.', self='Neighbours march on the granary or the store: join them, keep away, help the dealer, or inform.'),
    'comm.debts_forgiven': dict(name='Debts are forgiven', tone='good', line='A relief law caps old debts and writes off the smallest. Thousands of families open their post without dread.', self='A debt that shaped their life is lifted, or a loan they made is lost; either way the year starts over.'),
    'comm.licences_few': dict(name='Licences for the few', tone='bad', line='The city caps street-vendor permits, with a ten-year waiting list. Most vendors sell anyway and hope.', self='Their stall, cart or trade needs a licence they cannot get: pay, partner an insider, trade without, or leave.'),
    'comm.goods_underground': dict(name='Goods go underground', tone='mixed', line='Tobacco taxes jump. A man at the market sells cartons from his van, and everyone knows where to find him.', self='Cheap goods at the back door, an offer to carry crates at night: take it, refuse it, or report it.'),
    'comm.swindle': dict(name='A swindle is exposed', tone='bad', line="The investment club paid out from new members' money. When newcomers stop joining, the founder's phone goes dead.", self='Money they or their parents put in is gone; they may have urged a friend to join, or refused and been mocked.'),
    'comm.mania': dict(name='Everyone is buying', tone='mixed', line='House prices have risen every year for ten years. A friend buys a second flat with almost nothing down.', self='Everyone they know is buying: join early, join late, stay out and be called a fool, or sell at the top.'),
    'comm.coin_debased': dict(name='The coin loses its worth', tone='bad', line='Prices rise faster each month. Pensions buy less, and people keep their savings in anything but money.', self='Savings buy half what they did and wages lag; they spend fast, barter, or keep goods instead of coin.'),
    'comm.savings_circle': dict(name='Neighbours start a savings circle', tone='good', line='The market women start a rotating fund. This month it is her turn: enough for a second freezer.', self='A turn at the pot for a loom, a wedding or a stall; or holding the box and deciding about a late payer.'),
    'comm.bank_opens': dict(name='A money house opens', tone='good', line='A bank branch, then a phone account, reaches the village. A farmer borrows for a pump and repays in two seasons.', self="A first account, a loan for a stall or a roof, or a clerk's post; or a refusal they remember."),
    'comm.big_store': dict(name='The big store comes', tone='mixed', line="A superstore opens on the ring road. The town's grocer, butcher and hardware shop close within five years.", self="Cheaper shoes and a job on the tills, while the family shop or the neighbour's stall struggles."),
    'comm.cargo_lost': dict(name='The cargo does not come', tone='bad', line='A blocked shipping lane leaves the shelves empty of parts. The garage cannot fix the car for months.', self='A relative aboard, savings in the venture, or shelves empty of what they need.'),
    'comm.great_giving': dict(name='A great giving', tone='good', line="At the wedding, guests give envelopes, and the couple's mother writes every name and amount in a notebook.", self='They give beyond their means, or modestly; they receive gifts that will one day need returning.'),
    'comm.newcomers_trade': dict(name='Newcomers set up in trade', tone='mixed', line='The empty high street fills with shops run by families from abroad. Their children work the till after school.', self="New food, new neighbours, a job in their shop or a rival to one's own; or they are the newcomer."),
    'comm.new_money': dict(name='A new way to pay', tone='mixed', line='The market stall takes payment by phone. The old man at the next stall still wants cash.', self='Learning the new way to pay, or being left behind by it; an older relative who trusts only what they can hold.'),
    'comm.rents_jump': dict(name='Rents climb', tone='bad', line='The rent goes up a fifth at renewal. The family moves an hour out, and the children change schools.', self='More of the wage goes on a roof: move out, take a lodger, double up with kin, or join the tenants who refuse.'),
    'comm.hiring_fair': dict(name='A hiring place opens', tone='mixed', line='A job centre opens in the old bank. A young woman leaves with two interviews and a place on a forklift course.', self='They stand in the line to be picked, or do the picking: take the first offer, hold out, ask kin instead, or move on.'),
    'prot.raid_foiled': dict(name='The lookouts see them coming', tone='good', line='A cashier notices the same van circling the depot three days running and reports it. The robbery never happens.', self='A warning in time: they move the animals, bar the door or stand on the wall, and nothing is lost.'),
    'prot.call_up': dict(name='The call-up', tone='mixed', line='Reservists are called up and conscription is enforced again. The letters arrive within a week.', self='They or a sibling, partner or parent are called. A choice: go, volunteer early, seek an exemption, or refuse and bear the cost.'),
    'prot.siege': dict(name='The siege', tone='bad', line='The city is surrounded. Power and water fail by turns, the shops are bare, and neighbours cook together in the stairwell.', self='Hunger, fear and a turn on the wall: share the last stores, hoard them, carry water to the defenders, or slip out by night.'),
    'prot.peace_made': dict(name='Peace is made', tone='good', line='A ceasefire holds, then a treaty is signed. The reservists come home, and the border crossing reopens.', self='A sibling or friend comes home; a cousin marries across the old line; prices ease.'),
    'prot.veterans_home': dict(name='The fighters come home', tone='mixed', line='Discharged soldiers come back to a study grant and long waits at the clinic. Some thrive; some never settle.', self='A sibling or friend back, changed: a place at the table again, a silence that lasts years, old comrades at the tavern.'),
    'prot.safe_passage': dict(name='The road is made safe', tone='good', line='The shopkeepers on the main street share the cost of a night guard. The break-ins stop, and two shops reopen.', self='Work as a guard or with the caravans; goods from far away reach their market; a journey they could not make before.'),
    'prot.new_arms': dict(name='New arms and new drill', tone='mixed', line='Cheap radios and phone maps reach every patrol and volunteer crew. Drilled teams and street groups now do what only costly specialists could.', self='Drill on feast days with the new arm, a trade in making it, or a skill of their own suddenly worth less.'),
    'prot.watch_founded': dict(name='A watch is raised', tone='good', line="The council funds a team of local officers who walk the estate on foot and learn everyone's name.", self='Safer nights; a place opens in the watch; a neighbour they know now carries the lantern.'),
    'prot.crime_wave': dict(name='A crime wave', tone='bad', line="Break-ins jump on their side of town. The neighbours' group chat fills with doorbell-camera clips and rumours.", self='Safety falls: a break-in, a purse taken, a friend afraid to walk home. They lock up, move, or join a watch.'),
    'prot.racket': dict(name='A racket takes the street', tone='bad', line='A crew starts collecting from the late-night shops. Those who pay are left alone; the others get visits.', self="A weekly fee, or a friend's shop wrecked; a choice to pay, refuse, report it, or join."),
    'prot.heavy_hand': dict(name='The guard turns on the crowd', tone='bad', line='Riot police clear the protest camp at dawn. The videos have spread before breakfast.', self='A friend arrested or hurt in the square; a choice to march, to hide, or to keep wearing the uniform.'),
    'prot.crackdown': dict(name='A crackdown', tone='mixed', line='Fixed sentences, more patrols, more stops. The headlines calm, the prison fills, and whole streets learn to look down.', self='The streets feel safer to some; a cousin gets a long term for a small theft; stops and searches on the way home.'),
    'prot.neighbours_watch': dict(name='Neighbours keep their own watch', tone='good', line="The street starts a watch group and a phone tree. Burglaries fall, and people learn each other's names.", self='A rota, a whistle, a name for every neighbour; new ties, and nights they feel at home.'),
    'prot.walls_and_lamps': dict(name='Walls and lamps', tone='mixed', line='New street lights and cameras go up on the estate. Night crime falls; some feel safer, some feel watched.', self="Safer streets; a levy of labour or a new tax; the family's plot left outside the line, or work building it."),
    'prot.prison_reform': dict(name='A new way to punish', tone='good', line='The prison opens a college and a workshop. Within five years, far fewer of its leavers come back.', self='A relative inside learns a trade or comes home early under watch; they visit, and see a way back for someone.'),
    'prot.civil_war': dict(name='The realm splits in arms', tone='bad', line='Militias seize the north and the army splits. On the news is a checkpoint they drove through last spring.', self='A side to take, or not: enlist, hide a neighbour from the other side, deal with both, or leave while the roads are open.'),
    'prot.files_opened': dict(name="The watchers' files are opened", tone='mixed', line="A leak shows the city has tracked protesters' phones for years. Some shrug; some never trust a phone again.", self='They learn who reported on them, or that they were in a file; a friendship ends, or survives a hard talk.'),
    'prot.feud': dict(name='A feud flares', tone='bad', line="A row between two crews online spills into the street. Each side waits for the other's next move.", self='Their kin are a side: asked to take part, to drop friends across the line, or to try to end it.'),
    'prot.brave_stand': dict(name='Someone stands their ground', tone='good', line='A bus driver blocks the door against an armed man and keeps every passenger safe until the police arrive.', self='If it is them: a name, perhaps a scar, a door into the guard. If a friend: pride, and a pull to be braver.'),
    'prot.disaster_strikes': dict(name='Disaster strikes', tone='bad', line='The quake brings down three blocks on the old side of town. Rescue crews dig through the night, and a school gym becomes a shelter.', self='Home damaged or lost, a night in the shelter, a neighbour missing: dig, carry, give, take what is given, or leave for good.'),
    'prot.barrier_fails': dict(name='The barrier fails', tone='bad', line='The flood wall fails on the east side after three days of storm. Water fills the ground floors, and boats come down the high street.', self='Water in the house or the field, a night on the dyke with a spade, and a quarrel over who pays for the new wall.'),
}

